import os
import random
import string
from typing import List

# This generator produces UTF-8 bytes that represent a filesystem path string.
# It targets two fuzz stubs:
# - FUZZ_PARAM_FILENAME(): expects a real, existing path to exercise success paths.
# - FUZZ_PARAM_STR(): used as an arbitrary path candidate (relative/absolute), kept <=256 bytes.

COMMON_UNIX_DIRS = [
    "/tmp", "/var/tmp", "/var/log", "/usr/share", "/etc", "/home", "/root",
]
COMMON_UNIX_FILES = [
    "/etc/hosts", "/etc/passwd", "/etc/hostname", "/etc/resolv.conf",
]
COMMON_WIN_DRIVES = [
    "C:", "D:", "E:",
]
# Note: use double backslashes in string literals to avoid escape issues.
COMMON_WIN_DIRS = [
    "\\Windows", "\\Users", "\\Program Files", "\\ProgramData", "\\Temp",
]
COMMON_EXTS = [
    ".txt", ".cfg", ".ini", ".json", ".xml", ".qml", ".png", ".jpg", ".bin", ".dat",
]
UNICODE_SEGMENTS = [
    "数据", "ファイル", "файл", "ملف", "δείγμα", "archivo", "파일", "फ़ाइल", "😊",
]
RELATIVE_BASENAMES = [
    "README", "config", "settings", "cache", "boxart", "qmlcache", "log", "data",
]

SAFE_CHARS = string.ascii_letters + string.digits + "-_ ."


def _rand_filename(rng: random.Random) -> str:
    base = rng.choice(RELATIVE_BASENAMES)
    # Optionally add unicode
    if rng.random() < 0.4:
        base += "-" + rng.choice(UNICODE_SEGMENTS)
    # Optionally add extension
    if rng.random() < 0.8:
        base += rng.choice(COMMON_EXTS)
    # Maybe add numeric suffix
    if rng.random() < 0.5:
        base += str(rng.randrange(0, 1000))
    return base


def _rand_segments(rng: random.Random, min_n: int = 1, max_n: int = 4) -> List[str]:
    n = rng.randint(min_n, max_n)
    segs: List[str] = []
    for _ in range(n):
        choice = rng.random()
        if choice < 0.2:
            segs.append(".")
        elif choice < 0.35:
            segs.append("..")
        elif choice < 0.5:
            segs.append(_rand_filename(rng))
        elif choice < 0.7:
            # random token of safe chars
            l = rng.randint(1, 12)
            segs.append(''.join(rng.choice(SAFE_CHARS) for _ in range(l)).strip())
        elif choice < 0.85:
            segs.append(rng.choice(UNICODE_SEGMENTS))
        else:
            segs.append(_rand_filename(rng))
    return [s for s in segs if s != ""]


def _unix_path(rng: random.Random) -> str:
    # absolute or relative
    if rng.random() < 0.65:
        # absolute
        if rng.random() < 0.4:
            base = rng.choice(COMMON_UNIX_DIRS)
        elif rng.random() < 0.2:
            base = rng.choice(COMMON_UNIX_FILES)
        else:
            base = "/"
        segs = _rand_segments(rng)
        path = base.rstrip('/') + "/" + "/".join(segs)
    else:
        # relative
        prefix = ""
        roll = rng.random()
        if roll < 0.2:
            prefix = "./"
        elif roll < 0.35:
            prefix = "../"
        elif roll < 0.45:
            prefix = "~/."
        segs = _rand_segments(rng)
        path = prefix + "/".join(segs)
    # maybe add trailing slash
    if rng.random() < 0.2:
        path += "/"
    return path


def _windows_path(rng: random.Random) -> str:
    # Decide UNC vs drive
    if rng.random() < 0.25:
        # UNC path
        server = ''.join(rng.choice(string.ascii_letters + string.digits) for _ in range(rng.randint(3, 8)))
        share = ''.join(rng.choice(string.ascii_letters + string.digits) for _ in range(rng.randint(3, 8)))
        base = f"\\\\{server}\\{share}"
    else:
        drive = rng.choice(COMMON_WIN_DRIVES)
        base = drive
    # combine with common dirs sometimes
    if rng.random() < 0.4:
        base += rng.choice(COMMON_WIN_DIRS)
    segs = _rand_segments(rng)
    sep = "\\" if not base.endswith("\\") else ""
    path = base + sep + "\\".join(segs)
    # Possibly add extension if ends with directory-like
    if rng.random() < 0.3 and not any(path.lower().endswith(ext) for ext in COMMON_EXTS):
        path += rng.choice(COMMON_EXTS)
    return path


def _env_expanded_candidates(rng: random.Random) -> List[str]:
    # Provide common env var references that may expand on some systems
    cands = [
        "$HOME/.config/" + _rand_filename(rng),
        "$XDG_CACHE_HOME/" + _rand_filename(rng),
        "%TEMP%\\" + _rand_filename(rng),
        "%APPDATA%\\" + _rand_filename(rng),
    ]
    return cands


def _qml_related(rng: random.Random) -> List[str]:
    # Paths relevant to the library's Path use-cases (cache, logs, qml, box art)
    names = [
        "cache/qml/" + _rand_filename(rng),
        "cache/boxart/" + _rand_filename(rng),
        "logs/" + _rand_filename(rng),
        "data/" + _rand_filename(rng),
        "qmlcache/" + _rand_filename(rng),
    ]
    return names


def _pick_existing_like(rng: random.Random) -> str:
    # Prefer paths that often exist on typical systems to exercise read success.
    candidates: List[str] = []
    # Environment-driven
    try:
        home = os.path.expanduser("~")
    except Exception:
        home = ""
    if home:
        candidates += [
            os.path.join(home, ".bashrc"),
            os.path.join(home, ".profile"),
            os.path.join(home, ".gitconfig"),
            os.path.join(home, ".config", "user-dirs.dirs"),
        ]
    # Unix common
    candidates += COMMON_UNIX_FILES
    # Windows common
    if os.name == 'nt':
        userprofile = os.environ.get('USERPROFILE')
        if userprofile:
            candidates += [
                os.path.join(userprofile, "AppData", "Local", "Temp", _rand_filename(rng)),
                os.path.join(userprofile, "Desktop", _rand_filename(rng)),
            ]
        candidates += ["C:\\Windows\\win.ini", "C:\\Windows\\System32\\drivers\\etc\\hosts"]

    rng.shuffle(candidates)
    for p in candidates:
        try:
            if os.path.isfile(p) and os.access(p, os.R_OK):
                return p
        except Exception:
            pass
    # Fallback to syntactically valid known files; existence not guaranteed but plausible
    return rng.choice(candidates) if candidates else "/etc/hosts"


def generate(seed: int) -> bytes:
    rng = random.Random(seed)

    # Choose a generation mode targeting different stub behaviors
    mode = rng.random()

    if mode < 0.25:
        # Explicitly aim for an existing readable file path for readDataFile
        path = _pick_existing_like(rng)
    elif mode < 0.5:
        # Unix-style path
        path = _unix_path(rng)
    elif mode < 0.75:
        # Windows-style path
        path = _windows_path(rng)
    else:
        # Compose from env-expanded and library-related patterns
        pool = _env_expanded_candidates(rng) + _qml_related(rng)
        # Mix with absolute prefix sometimes
        if rng.random() < 0.5:
            pool.append(_unix_path(rng))
        if rng.random() < 0.5:
            pool.append(_windows_path(rng))
        path = rng.choice(pool)

    # Ensure length constraints (fuzzer stub truncates to 256 for FUZZ_PARAM_STR)
    max_len = 256
    enc = path.encode('utf-8', errors='ignore')
    if len(enc) > max_len:
        # Truncate carefully at character boundaries
        out_chars = []
        total = 0
        for ch in path:
            b = ch.encode('utf-8')
            if total + len(b) > max_len:
                break
            out_chars.append(ch)
            total += len(b)
        path = ''.join(out_chars)

    return path.encode('utf-8')
